		public var ratingChart: TrendsRatingChart
		public var rounds: [TrendsRound]
		public var timeControls: [TrendsTimeControl]
		public var upsets: TrendsUpsets
		/// Ascending by date.
		public var winRate: [TrendsWinRatePoint]
		public var winRateByWeekday: [TrendsWeekday]

		public init(averageLength: TrendsAverageLength, calendar: [TrendsCalendarYear], gameLengths: [TrendsGameLength], gamesCount: Int, gamesPerMonth: [TrendsMonth], ratingChart: TrendsRatingChart, rounds: [TrendsRound], timeControls: [TrendsTimeControl], upsets: TrendsUpsets, winRate: [TrendsWinRatePoint], winRateByWeekday: [TrendsWeekday]) {
			self.averageLength = averageLength
			self.calendar = calendar
			self.gameLengths = gameLengths
			self.gamesCount = gamesCount
			self.gamesPerMonth = gamesPerMonth
			self.ratingChart = ratingChart
			self.rounds = rounds
			self.timeControls = timeControls
			self.upsets = upsets
			self.winRate = winRate
			self.winRateByWeekday = winRateByWeekday
		}

		enum CodingKeys: String, CodingKey {
			case averageLength = "average_length"
			case calendar = "calendar"
			case gameLengths = "game_lengths"
			case gamesCount = "games_count"
			case gamesPerMonth = "games_per_month"
			case ratingChart = "rating_chart"
			case rounds = "rounds"
			case timeControls = "time_controls"
			case upsets = "upsets"
			case winRate = "win_rate"
			case winRateByWeekday = "win_rate_by_weekday"
		}
	}

	/// uscf: the dual-line Official/Live chart, chosen when either full USCF series exists (before date trimming). typed: USCF never reached or not configured, so the chart degrades to typed header ratings.
	public enum TrendsRatingChartMode: String, Codable, Sendable, Hashable, CaseIterable {
		case uscf = "uscf"
		case typed = "typed"
	}

	/// "Your rating over time". All three arrays empty is the empty state ("No rating data", or "No rating data in this date range" in uscf mode).
	public struct TrendsRatingChart: Codable, Sendable, Hashable {
		/// Which line is full strength (the active lens); the other recedes but is always drawn. The lens hides nothing here.
		public var emphasized: Lens
		/// mode uscf only (else []). Trimmed to start/end.
		public var live: [TrendsLivePoint]
		/// uscf: the dual-line Official/Live chart, chosen when either full USCF series exists (before date trimming). typed: USCF never reached or not configured, so the chart degrades to typed header ratings.
		public var mode: TrendsRatingChartMode
		/// mode uscf only (else []). Trimmed to start/end; no other filter applies to rating series.
		public var official: [TrendsOfficialPoint]
		/// mode typed only (else []). Follows every filter.
		public var typed: [TrendsTypedPoint]

		public init(emphasized: Lens, live: [TrendsLivePoint], mode: TrendsRatingChartMode, official: [TrendsOfficialPoint], typed: [TrendsTypedPoint]) {
			self.emphasized = emphasized
			self.live = live
			self.mode = mode
			self.official = official
			self.typed = typed
		}

		enum CodingKeys: String, CodingKey {
			case emphasized = "emphasized"
			case live = "live"
			case mode = "mode"
			case official = "official"
			case typed = "typed"
		}
	}

	/// One bar of "Score by round: the fatigue check". Ascending by round.
	public struct TrendsRound: Codable, Sendable, Hashable {
		public var draw: Int
		public var games: Int
		public var loss: Int
		/// games >= 3. Unreliable rounds render dimmed with "too few to conclude".
		public var reliable: Bool
		/// The round number: the USCF crosstable round when matched, else the typed Round header.
		public var round: Int
		/// (win + draw/2) / games as 0..100, one decimal. The bar height.
		public var scorePct: Double
		public var win: Int
		/// 0..100, one decimal.
		public var winRatePct: Double

		public init(draw: Int, games: Int, loss: Int, reliable: Bool, round: Int, scorePct: Double, win: Int, winRatePct: Double) {
			self.draw = draw
			self.games = games
			self.loss = loss
			self.reliable = reliable
			self.round = round
			self.scorePct = scorePct
			self.win = win
			self.winRatePct = winRatePct
		}

		enum CodingKeys: String, CodingKey {
			case draw = "draw"
			case games = "games"
			case loss = "loss"
			case reliable = "reliable"
			case round = "round"
			case scorePct = "score_pct"
			case win = "win"
			case winRatePct = "win_rate_pct"
		}
	}

	/// From estimated minutes: 60+ Classical, 10+ Rapid, else Blitz; Unknown when unparseable.
	public enum TrendsTimeControlSpeed: String, Codable, Sendable, Hashable, CaseIterable {
		case classical = "Classical"
		case rapid = "Rapid"
		case blitz = "Blitz"
		case unknown = "Unknown"
	}

	/// One stacked bar of "Results by time control". Finished, non-Forfeit Games; slowest first, unparseable last.
	public struct TrendsTimeControl: Codable, Sendable, Hashable {
		public var draw: Int
		public var games: Int
		public var loss: Int
		/// Estimated total thinking time per player in minutes (base + one minute per second of increment); null when unparseable.
		public var minutes: Double?
		/// From estimated minutes: 60+ Classical, 10+ Rapid, else Blitz; Unknown when unparseable.
		public var speed: TrendsTimeControlSpeed
		/// The TimeControl header verbatim; "" when not recorded (the web labels it "(not recorded)").
		public var timeControl: String
		public var win: Int
		/// 0..100, one decimal.
		public var winRatePct: Double

		public init(draw: Int, games: Int, loss: Int, minutes: Double? = nil, speed: TrendsTimeControlSpeed, timeControl: String, win: Int, winRatePct: Double) {
			self.draw = draw
			self.games = games
			self.loss = loss
			self.minutes = minutes
			self.speed = speed
			self.timeControl = timeControl
			self.win = win
			self.winRatePct = winRatePct
		}

		enum CodingKeys: String, CodingKey {
			case draw = "draw"
			case games = "games"
			case loss = "loss"
			case minutes = "minutes"
			case speed = "speed"
			case timeControl = "time_control"
			case win = "win"
			case winRatePct = "win_rate_pct"
		}
	}

	/// One point of the fallback chart, from the Studies' typed ratings.
	public struct TrendsTypedPoint: Codable, Sendable, Hashable {
		/// The day (never null here).
		public var date: IsoDate?
		/// The hand-typed header rating on the day's last Game, under the active lens.
		public var rating: Rating?
		/// The linear-trend line value at this point (least-squares fit over point index); null on every point when there are fewer than 3 points.
		public var trend: Double?

		public init(date: IsoDate? = nil, rating: Rating? = nil, trend: Double? = nil) {
			self.date = date
			self.rating = rating
			self.trend = trend
		}

		enum CodingKeys: String, CodingKey {
			case date = "date"
			case rating = "rating"
			case trend = "trend"
		}
	}

	/// One upset row; tap opens the Game.
	public struct TrendsUpset: Codable, Sendable, Hashable {
		public var game: GameSummary
		/// Rating points between the two players, unsigned (the web shows + for giant kills, − for upset losses).
		public var margin: Int

		public init(game: GameSummary, margin: Int) {
			self.game = game
			self.margin = margin
		}

		enum CodingKeys: String, CodingKey {
			case game = "game"
			case margin = "margin"
		}
	}

	/// The upset tracker. Each list empty shows its own explanatory line.
	public struct TrendsUpsets: Codable, Sendable, Hashable {
		/// Wins over higher-rated opponents, biggest margin first. Both ratings known; Forfeits never count.
		public var giantKills: [TrendsUpset]
		/// Losses to lower-rated opponents, biggest margin first.
		public var upsetLosses: [TrendsUpset]

		public init(giantKills: [TrendsUpset], upsetLosses: [TrendsUpset]) {
			self.giantKills = giantKills
			self.upsetLosses = upsetLosses
		}

		enum CodingKeys: String, CodingKey {
			case giantKills = "giant_kills"
			case upsetLosses = "upset_losses"
		}
	}

	public enum TrendsWeekdayDayOfWeek: String, Codable, Sendable, Hashable, CaseIterable {
		case mon = "Mon"
		case tue = "Tue"
		case wed = "Wed"
		case thu = "Thu"
		case fri = "Fri"
		case sat = "Sat"
		case sun = "Sun"
	}

	/// One bar of "Win rate by day of week" (weekdays with Games only, Mon to Sun).
	public struct TrendsWeekday: Codable, Sendable, Hashable {
		public var dayOfWeek: TrendsWeekdayDayOfWeek
		public var games: Int
		/// 0..100, one decimal. The bar height; the web colors it on a 30..70 scale with a 50% line.
		public var winRatePct: Double
		public var wins: Int

		public init(dayOfWeek: TrendsWeekdayDayOfWeek, games: Int, winRatePct: Double, wins: Int) {
			self.dayOfWeek = dayOfWeek
			self.games = games
			self.winRatePct = winRatePct
			self.wins = wins
		}

		enum CodingKeys: String, CodingKey {
			case dayOfWeek = "day_of_week"
			case games = "games"
			case winRatePct = "win_rate_pct"
			case wins = "wins"
		}
	}

	/// One point of the cumulative win rate (one per day, finished, dated, non-Forfeit Games). The web draws a 50% reference line.
	public struct TrendsWinRatePoint: Codable, Sendable, Hashable {
		public var cumGames: Int
		public var cumWins: Int
		/// The day (never null here).
		public var date: IsoDate?
		/// Cumulative win rate 0..100 through this day (unrounded).
		public var winRatePct: Double

		public init(cumGames: Int, cumWins: Int, date: IsoDate? = nil, winRatePct: Double) {
			self.cumGames = cumGames
			self.cumWins = cumWins
			self.date = date
			self.winRatePct = winRatePct
		}

		enum CodingKeys: String, CodingKey {
			case cumGames = "cum_games"
			case cumWins = "cum_wins"
			case date = "date"
			case winRatePct = "win_rate_pct"
		}
	}

	/// The Game's USCF status, as the web Games table shows it: matched by member ID, matched by name, matched but the sources disagree (see Reconciliation), a Forfeit, or no USCF Game Record.
	public enum UscfMatchStatus: String, Codable, Sendable, Hashable, CaseIterable {
		case matchedById = "matched_by_id"
		case matchedByName = "matched_by_name"
		case conflict = "conflict"
		case forfeit = "forfeit"
		case unmatched = "unmatched"
	}
}

/// One factory per operation: `try await api.send(Endpoints.getMeta())`.
public enum Endpoints {
	/// Sign in and get a bearer token
	public static func createSession(body: API.SessionRequest) -> Endpoint<API.SessionGrant> {
		Endpoint(
			operationId: "createSession", method: .post, path: "session",
			query: [], body: jsonBody(body), authenticated: false)
	}

	/// The Analysis screen: the Error Profile across every analysed Game.
	public static func getAnalysis() -> Endpoint<API.AnalysisPayload> {
		Endpoint(
			operationId: "getAnalysis", method: .get, path: "analysis",
			query: [], body: nil, authenticated: true)
	}

	/// One Rated Event: its Sections, placement, rating change, Games, and full crosstables.
	public static func getEvent(eventId: String, filters: FilterState) -> Endpoint<API.EventPayload> {
		Endpoint(
			operationId: "getEvent", method: .get, path: "events/\(pathSegment(eventId))",
			query: filters.queryItems, body: nil, authenticated: true)
	}

	/// The Events screen: each Series and the Rated Events inside it.
	public static func getEvents(filters: FilterState) -> Endpoint<API.EventsPayload> {
		Endpoint(
			operationId: "getEvents", method: .get, path: "events",
			query: filters.queryItems, body: nil, authenticated: true)
	}

	/// One Game in full: board PGNs, Engine view, Lessons, Tags, metadata, USCF Game Record.
	public static func getGame(gameId: API.GameId) -> Endpoint<API.GamePayload> {
		Endpoint(
			operationId: "getGame", method: .get, path: "games/\(pathSegment(gameId))",
			query: [], body: nil, authenticated: true)
	}

	/// Every Game, filtered
	public static func getGames(filters: FilterState) -> Endpoint<API.GamesPayload> {
		Endpoint(
			operationId: "getGames", method: .get, path: "games",
			query: filters.queryItems, body: nil, authenticated: true)
	}

	/// The Lessons screen, with optional pre-game review mode
	public static func getLessons(tags: [String]? = nil, opponent: String? = nil, review: Bool? = nil, filters: FilterState) -> Endpoint<API.LessonsPayload> {
		Endpoint(
			operationId: "getLessons", method: .get, path: "lessons",
			query: filters.queryItems + query("tags", tags) + query("opponent", opponent) + query("review", review), body: nil, authenticated: true)
	}

	/// Who is signed in, filter options, presets, freshness
	public static func getMeta() -> Endpoint<API.MetaPayload> {
		Endpoint(
			operationId: "getMeta", method: .get, path: "meta",
			query: [], body: nil, authenticated: true)
	}

	/// The Openings screen: repertoire tree, ECO families, top openings.
	public static func getOpenings(filters: FilterState) -> Endpoint<API.OpeningsPayload> {
		Endpoint(
			operationId: "getOpenings", method: .get, path: "openings",
			query: filters.queryItems, body: nil, authenticated: true)
	}

	/// One opponent's Scouting Report
	public static func getOpponent(opponentId: API.OpponentId, filters: FilterState) -> Endpoint<API.OpponentPayload> {
		Endpoint(
			operationId: "getOpponent", method: .get, path: "opponents/\(pathSegment(opponentId))",
			query: filters.queryItems, body: nil, authenticated: true)
	}

	/// The Opponents screen
	public static func getOpponents(filters: FilterState) -> Endpoint<API.OpponentsPayload> {
		Endpoint(
			operationId: "getOpponents", method: .get, path: "opponents",
			query: filters.queryItems, body: nil, authenticated: true)
	}

	/// The Overview screen
	public static func getOverview(filters: FilterState) -> Endpoint<API.OverviewPayload> {
		Endpoint(
			operationId: "getOverview", method: .get, path: "overview",
			query: filters.queryItems, body: nil, authenticated: true)
	}

	/// The Trends screen
	public static func getTrends(filters: FilterState) -> Endpoint<API.TrendsPayload> {
		Endpoint(
			operationId: "getTrends", method: .get, path: "trends",
			query: filters.queryItems, body: nil, authenticated: true)
	}

	/// Run a Sync (owner only) and return what the web toast shows.
	public static func runSync() -> Endpoint<API.SyncPayload> {
		Endpoint(
			operationId: "runSync", method: .post, path: "sync",
			query: [], body: nil, authenticated: true)
	}
}
